from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass

logger = BackgroundLogger.Instance()


class SWOperationsRC(AdminBaseClass):
    """Alarms"""
    def __init__(self):
        super(SWOperationsRC, self).__init__()

    def software_management_rc(self, **kwargs):
        operation = kwargs.pop('operation')
        return getattr(self, '_{}'.format(operation.lower()))(**kwargs)

    def _get_active_sw_partition(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.admin.get_active_sw_partition(timeout=timeout, connection=connection)

    def software_update(self, **kwargs):
        sw_slot_id = kwargs['sw_slot_id']
        sw_pkg_path = kwargs['sw_pkg_path']
        activate = kwargs.get('activate', False)
        # timeout = kwargs.get('timeout', 900)
        connection = kwargs.get('alias', 'default')
        # activation_options will be sent in kwargs if passed by user.
        return self.factory.rcconnect.software_update(sw_slot_id, sw_pkg_path, activate=activate,
                                                      connection=connection, activation_options=['deleteCertificates', 'deleteCredentials'])

    def download_autoconfiguration_report(self, **kwargs):
        path = kwargs['path']
        timeout = kwargs.get('timeout', 10)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.download_autoconfiguration_report(path=path, timeout=timeout, connection=connection)


